<script setup lang="ts">
import { useMessage } from 'naive-ui'
definePageMeta({ layout: 'admin' }); useSeoMeta({ title: '\u7ba1\u7406\u5458\u8d44\u6599' })
const api=useApi(),message=useMessage(),confirm=useConfirm(),{account,load}=useAuth()
const displayName=ref(account.value?.displayName||''),avatarAssetId=ref<number|null>(account.value?.avatarAssetId||null),busy=ref(false),uploading=ref(false),passwordBusy=ref(false)
const currentPassword=ref(''),newPassword=ref(''),repeatPassword=ref('')
const dirty=computed(()=>displayName.value!==(account.value?.displayName||'')||avatarAssetId.value!==(account.value?.avatarAssetId||null))
useUnsavedChanges(computed(()=>dirty.value||uploading.value||!!currentPassword.value||!!newPassword.value||!!repeatPassword.value))
async function save(){busy.value=true;try{await api('/api/admin/account/profile',{method:'PUT',body:{displayName:displayName.value,avatarAssetId:avatarAssetId.value,lockVersion:account.value!.lockVersion}});await load();displayName.value=account.value!.displayName;avatarAssetId.value=account.value!.avatarAssetId;message.success('\u7ba1\u7406\u5458\u8d44\u6599\u5df2\u4fdd\u5b58')}catch(e){message.error(errorText(e))}finally{busy.value=false}}
async function changePassword(){if(dirty.value||uploading.value||busy.value){message.warning('\u8bf7\u5148\u4fdd\u5b58\u7ba1\u7406\u5458\u8d44\u6599\uff0c\u518d\u4fee\u6539\u5bc6\u7801');return}if(newPassword.value!==repeatPassword.value){message.error('\u4e24\u6b21\u65b0\u5bc6\u7801\u4e0d\u4e00\u81f4');return}if(!await confirm('\u4fee\u6539\u7ba1\u7406\u5458\u5bc6\u7801\uff1f','\u4fee\u6539\u6210\u529f\u540e\uff0c\u6240\u6709\u8bbe\u5907\u4e0a\u7684\u4f1a\u8bdd\u5c06\u5931\u6548\uff0c\u9700\u8981\u91cd\u65b0\u767b\u5f55\u3002'))return;passwordBusy.value=true;try{await api('/api/admin/account/password',{method:'POST',body:{currentPassword:currentPassword.value,newPassword:newPassword.value,lockVersion:account.value!.lockVersion}});currentPassword.value='';newPassword.value='';repeatPassword.value='';message.success('\u5bc6\u7801\u5df2\u4fee\u6539\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55');await navigateTo('/admin/login')}catch(e){message.error(errorText(e))}finally{passwordBusy.value=false}}
</script>
